SELECT min(qty), max(qty), count(*) FILTER (WHERE qty<=0) nonpos, count(*) FILTER (WHERE sku_scanned IS NULL) nullsku,
       count(*) FILTER (WHERE gtin_scanned NOT IN (SELECT gtin FROM store.products)) badgtin,
       count(DISTINCT sku_scanned) skus
FROM store.pos_lines;
SELECT DISTINCT note FROM payments.pos_payments WHERE note IS NOT NULL AND note <> '' LIMIT 20;

SELECT count(*) total, count(*) FILTER (WHERE note IS NOT NULL AND note <> '') with_note FROM payments.pos_payments;
SELECT sku, count(*) audits, count(*) FILTER (WHERE status='empty') empty FROM store.shelf_audits GROUP BY 1 HAVING count(*) FILTER (WHERE status='empty')>0;
SELECT sku, count_ts, book_before, counted, adjustment, trigger FROM store.stock_counts ORDER BY count_ts;
